using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.RegularExpressions;
using Keynote.Core;
namespace Keynote.Online;
public record CatalogResult(string Provider,string Id,string Title,string Artist,string Description,string License,string SourceUrl,double? Rating=null,string? Sha256=null,IReadOnlyList<CatalogSource>? Sources=null,string? DirectUrl=null,int? RecommendedOctave=null) { public override string ToString()=>$"{Title}  •  {Provider}"; }
public record CatalogPage(IReadOnlyList<CatalogResult> Results,bool HasMore);
public record LibraryEntry(string Sha256,string Title,string Artist,string Provider,string Source,string License,DateTimeOffset AddedUtc,IReadOnlyList<CatalogSource>? Sources=null,int? RecommendedOctave=null) { public override string ToString()=>$"{Title}  •  {Provider}  •  {AddedUtc.LocalDateTime:yyyy-MM-dd}"; }
public interface IMidiCatalogProvider { Task<CatalogPage> SearchAsync(string query,int page,CancellationToken token); Uri DownloadUri(CatalogResult result); }
public interface IMidiDownloadService { Task<byte[]> DownloadAsync(Uri uri,IProgress<double>? progress,CancellationToken token); }
public interface IMidiLibraryService { Task<(LibraryEntry Entry,bool Duplicate)> AddAsync(byte[] data,CatalogResult metadata,CancellationToken token); Task<IReadOnlyList<LibraryEntry>> ListAsync(CancellationToken token); Task<string> OpenAsync(LibraryEntry entry,CancellationToken token); Task RemoveAsync(LibraryEntry entry,CancellationToken token); }
public interface ISongToMidiProvider { Task<string> SubmitAsync(string kind,string? value,string? file,CancellationToken token); Task<TranscriptionStatus> GetStatusAsync(string id,CancellationToken token); Uri DownloadUri(string id); }
public record TranscriptionStatus(string Status,string Stage,double? Progress,string? Error,string? Source);
public sealed class MidiDownloadService(HttpClient http) : IMidiDownloadService {
 public const int MaxBytes=10*1024*1024;
 public static HttpClient CreateClient() => new(new SocketsHttpHandler { AllowAutoRedirect=false, AutomaticDecompression=DecompressionMethods.All, ConnectTimeout=TimeSpan.FromSeconds(15) }) { Timeout=TimeSpan.FromSeconds(45) };
 public static void ValidateEndpoint(Uri uri) { if(uri.Scheme!=Uri.UriSchemeHttps || !uri.IsDefaultPort || !string.IsNullOrEmpty(uri.UserInfo) || !(uri.Host.Equals("midisss.com",StringComparison.OrdinalIgnoreCase)||uri.Host.Equals("api.opennan.com",StringComparison.OrdinalIgnoreCase)||(uri.Host.Equals("larpiano.portways.app",StringComparison.OrdinalIgnoreCase) && Regex.IsMatch(uri.AbsolutePath,@"^/api/remapped/songs/[0-9a-f]{64}/midi$",RegexOptions.CultureInvariant) && string.IsNullOrEmpty(uri.Query) && string.IsNullOrEmpty(uri.Fragment))||((uri.Host.Equals("www.mutopiaproject.org",StringComparison.OrdinalIgnoreCase)||uri.Host.Equals("mutopiaproject.org",StringComparison.OrdinalIgnoreCase)) && uri.AbsolutePath.StartsWith("/ftp/",StringComparison.Ordinal) && uri.AbsolutePath.EndsWith(".mid",StringComparison.OrdinalIgnoreCase) && string.IsNullOrEmpty(uri.Query) && string.IsNullOrEmpty(uri.Fragment)))) throw new InvalidOperationException("Only approved HTTPS provider endpoints are allowed."); }
 public async Task<byte[]> DownloadAsync(Uri uri,IProgress<double>? progress,CancellationToken token) {
  ValidateEndpoint(uri); using var response=await http.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,token); response.EnsureSuccessStatusCode(); var size=response.Content.Headers.ContentLength; if(size>MaxBytes)throw new InvalidDataException("MIDI exceeds the 10 MB limit.");
  await using var source=await response.Content.ReadAsStreamAsync(token); using var dest=new MemoryStream(); var buffer=new byte[16384]; int n; while((n=await source.ReadAsync(buffer,token))>0) { if(dest.Length+n>MaxBytes)throw new InvalidDataException("MIDI exceeds the 10 MB limit."); await dest.WriteAsync(buffer.AsMemory(0,n),token); if(size>0)progress?.Report((double)dest.Length/size.Value); }
  var data=dest.ToArray(); if(data.Length<14 || !data.AsSpan(0,4).SequenceEqual("MThd"u8))throw new InvalidDataException("The response is not a Standard MIDI file."); return data;
 }
}
public sealed class MidisssCatalogProvider(HttpClient http) : IMidiCatalogProvider {
 readonly SemaphoreSlim throttle=new(1,1); DateTimeOffset lastRequest=DateTimeOffset.MinValue;
 public async Task<CatalogPage> SearchAsync(string query,int page,CancellationToken token) {
  if(page!=0)throw new NotSupportedException("MIDIsss does not document pagination."); if(string.IsNullOrWhiteSpace(query))return new(Array.Empty<CatalogResult>(),false); if(query.Length>200)throw new ArgumentException("Search is limited to 200 characters.");
  await throttle.WaitAsync(token); try { var remaining=TimeSpan.FromSeconds(1)-(DateTimeOffset.UtcNow-lastRequest); if(remaining>TimeSpan.Zero)await Task.Delay(remaining,token); lastRequest=DateTimeOffset.UtcNow; } finally { throttle.Release(); }
  var uri=new Uri("https://midisss.com/api.php?action=search&q="+Uri.EscapeDataString(query.Trim())); using var response=await http.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,token); response.EnsureSuccessStatusCode(); if(response.Content.Headers.ContentLength>1024*1024)throw new InvalidDataException("Search response is too large."); await using var stream=await response.Content.ReadAsStreamAsync(token); using var limited=new MemoryStream(); var buf=new byte[8192]; int n; while((n=await stream.ReadAsync(buf,token))>0) { if(limited.Length+n>1024*1024)throw new InvalidDataException("Search response is too large."); limited.Write(buf,0,n); } limited.Position=0;
  using var doc=await JsonDocument.ParseAsync(limited,cancellationToken:token); if(doc.RootElement.ValueKind!=JsonValueKind.Array)throw new InvalidDataException("Unexpected MIDIsss search response."); var list=new List<CatalogResult>(); foreach(var row in doc.RootElement.EnumerateArray()) { if(!row.TryGetProperty("id",out var id)||!id.TryGetInt64(out long number)||number<=0 || !row.TryGetProperty("name",out var title)||title.ValueKind!=JsonValueKind.String)continue; var notes=row.TryGetProperty("notes",out var note)&&note.ValueKind==JsonValueKind.String?note.GetString()??"":""; double? rating=row.TryGetProperty("average_rating",out var rt)&&rt.ValueKind==JsonValueKind.Number&&rt.TryGetDouble(out var score) && score>0 ? score : null; list.Add(new("MIDIsss",number.ToString(System.Globalization.CultureInfo.InvariantCulture),title.GetString()??"Untitled","Unknown",notes,"Personal and educational use; other uses require permission.","https://midisss.com/api.php?action=get_midi&id="+number.ToString(System.Globalization.CultureInfo.InvariantCulture),rating)); } return new(list.DistinctBy(x=>x.Id).ToArray(),false);
 }
 public Uri DownloadUri(CatalogResult result) { if(result.Provider!="MIDIsss" || !long.TryParse(result.Id,out long id)||id<=0)throw new ArgumentException("Invalid MIDIsss ID."); return new($"https://midisss.com/api.php?action=get_midi&id={id}"); }
}
public sealed class MidiLibraryService(string directory,IMidiImporter importer) : IMidiLibraryService {
 readonly SemaphoreSlim mutex=new(1,1); readonly string root=Path.GetFullPath(directory);
 static bool ValidHash(string h)=>h.Length==64 && h.All(c=>c is >= '0' and <= '9' or >= 'a' and <= 'f');
 string PathFor(string hash,string extension) { if(!ValidHash(hash))throw new InvalidDataException("Invalid library identifier."); return Path.Combine(root,hash+extension); }
 static string Hash(byte[] bytes)=>Convert.ToHexStringLower(SHA256.HashData(bytes));
 async Task WriteMetadata(LibraryEntry entry,CancellationToken token) { var temp=Path.Combine(root,Guid.NewGuid().ToString("N")+".tmp"); try { await File.WriteAllTextAsync(temp,JsonSerializer.Serialize(entry),token); File.Move(temp,PathFor(entry.Sha256,".json"),true); } finally { if(File.Exists(temp))File.Delete(temp); } }
 public async Task<(LibraryEntry Entry,bool Duplicate)> AddAsync(byte[] data,CatalogResult metadata,CancellationToken token) { if(data.Length<14 || data.Length>MidiDownloadService.MaxBytes || !data.AsSpan(0,4).SequenceEqual("MThd"u8))throw new InvalidDataException("Invalid MIDI content."); await mutex.WaitAsync(token); try { Directory.CreateDirectory(root); var hash=Hash(data); var path=PathFor(hash,".mid"); if(File.Exists(path)) { var actual=Hash(await File.ReadAllBytesAsync(path,token)); if(actual!=hash)throw new InvalidDataException("Existing library file failed integrity verification."); var existing=await ReadEntry(hash,token); var sources=(existing.Sources ?? new[]{new CatalogSource(existing.Provider,"",existing.Source,existing.License)}).Concat(metadata.Sources ?? new[]{new CatalogSource(metadata.Provider,metadata.Id,metadata.SourceUrl,metadata.License)}).DistinctBy(x=>(x.Provider,x.SourceUrl)).ToArray(); existing=existing with { Sources=sources, RecommendedOctave=existing.RecommendedOctave ?? metadata.RecommendedOctave }; await WriteMetadata(existing,token); return (existing,true); }
  var temp=Path.Combine(root,Guid.NewGuid().ToString("N")+".mid"); try { await File.WriteAllBytesAsync(temp,data,token); await Task.Run(()=>importer.Import(temp),token); token.ThrowIfCancellationRequested(); File.Move(temp,path); var entry=new LibraryEntry(hash,metadata.Title,metadata.Artist,metadata.Provider,metadata.SourceUrl,metadata.License,DateTimeOffset.UtcNow,metadata.Sources ?? new[]{new CatalogSource(metadata.Provider,metadata.Id,metadata.SourceUrl,metadata.License)},metadata.RecommendedOctave); await WriteMetadata(entry,token); return(entry,false); } finally { if(File.Exists(temp))File.Delete(temp); }
 } finally { mutex.Release(); } }
 async Task<LibraryEntry> ReadEntry(string hash,CancellationToken token) { var path=PathFor(hash,".json"); try { if(File.Exists(path)) { var data=await File.ReadAllTextAsync(path,token); var e=JsonSerializer.Deserialize<LibraryEntry>(data); if(e!=null && e.Sha256==hash && !string.IsNullOrWhiteSpace(e.Title))return e; } } catch(JsonException) { } var recovered=new LibraryEntry(hash,"Recovered MIDI "+hash[..8],"Unknown","Unknown","","License unknown",File.GetLastWriteTimeUtc(PathFor(hash,".mid"))); await WriteMetadata(recovered,token); return recovered; }
 public async Task<IReadOnlyList<LibraryEntry>> ListAsync(CancellationToken token) { await mutex.WaitAsync(token); try { Directory.CreateDirectory(root); var list=new List<LibraryEntry>(); foreach(var path in Directory.EnumerateFiles(root,"*.mid")) { token.ThrowIfCancellationRequested(); var hash=Path.GetFileNameWithoutExtension(path); if(ValidHash(hash))list.Add(await ReadEntry(hash,token)); } foreach(var path in Directory.EnumerateFiles(root,"*.json")) { token.ThrowIfCancellationRequested(); var hash=Path.GetFileNameWithoutExtension(path); if(!ValidHash(hash) || File.Exists(PathFor(hash,".mid")))continue; try { var entry=JsonSerializer.Deserialize<LibraryEntry>(await File.ReadAllTextAsync(path,token)); if(entry!=null && entry.Sha256==hash && !string.IsNullOrWhiteSpace(entry.Title))list.Add(entry); } catch(JsonException) { } } return list.OrderByDescending(e=>e.AddedUtc).ToArray(); } finally { mutex.Release(); } }
 public async Task<string> OpenAsync(LibraryEntry entry,CancellationToken token) { var path=PathFor(entry.Sha256,".mid"); if(!File.Exists(path))throw new FileNotFoundException("Library MIDI file is missing."); var info=new FileInfo(path); if(info.Length>MidiDownloadService.MaxBytes)throw new InvalidDataException("Library file exceeds the size limit."); var data=await File.ReadAllBytesAsync(path,token); if(Hash(data)!=entry.Sha256)throw new InvalidDataException("Library file failed SHA-256 verification."); await Task.Run(()=>importer.Import(path),token); return path; }
 public async Task<LibraryEntry> SetRecommendedOctaveAsync(LibraryEntry entry,int octave,CancellationToken token) { if(octave is < -2 or > 2)throw new ArgumentOutOfRangeException(nameof(octave)); await mutex.WaitAsync(token); try { token.ThrowIfCancellationRequested(); var current=await ReadEntry(entry.Sha256,token); if(!File.Exists(PathFor(entry.Sha256,".mid")))throw new FileNotFoundException("Library MIDI file is missing."); current=current with { RecommendedOctave=octave }; await WriteMetadata(current,token); return current; } finally { mutex.Release(); } }
 public async Task RemoveAsync(LibraryEntry entry,CancellationToken token) { await mutex.WaitAsync(token); try { token.ThrowIfCancellationRequested(); File.Delete(PathFor(entry.Sha256,".mid")); File.Delete(PathFor(entry.Sha256,".json")); } finally { mutex.Release(); } }
}
